package com.example.lending.domain;

import org.junit.jupiter.api.Test;

import java.time.LocalDate;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class LoanLateFeeTest {

    private static final LocalDate LOANED_AT = LocalDate.of(2026, 1, 1);

    @Test
    void returning_on_the_due_date_has_no_fee() {
        Loan loan = loanReturnedOn(LocalDate.of(2026, 1, 15));

        assertThat(loan.overdueDays()).isZero();
        assertThat(loan.lateFee()).isZero();
    }

    @Test
    void each_day_after_the_due_date_costs_100_won() {
        assertThat(loanReturnedOn(LocalDate.of(2026, 1, 16)).overdueDays()).isEqualTo(1);
        assertThat(loanReturnedOn(LocalDate.of(2026, 1, 16)).lateFee()).isEqualTo(100);
        assertThat(loanReturnedOn(LocalDate.of(2026, 1, 20)).overdueDays()).isEqualTo(5);
        assertThat(loanReturnedOn(LocalDate.of(2026, 1, 20)).lateFee()).isEqualTo(500);
    }

    @Test
    void returning_before_the_due_date_has_no_fee() {
        assertThat(loanReturnedOn(LocalDate.of(2026, 1, 3)).lateFee()).isZero();
    }

    @Test
    void fee_is_not_available_before_the_loan_is_returned() {
        Loan loan = Loan.reconstitute(UUID.randomUUID(), UUID.randomUUID(), UUID.randomUUID(),
                LOANED_AT, LOANED_AT.plusDays(14), null);

        assertThatThrownBy(loan::lateFee).isInstanceOf(IllegalStateException.class);
    }

    @Test
    void returned_date_cannot_be_before_the_loan_date() {
        Loan loan = Loan.reconstitute(UUID.randomUUID(), UUID.randomUUID(), UUID.randomUUID(),
                LOANED_AT, LOANED_AT.plusDays(14), null);

        assertThatThrownBy(() -> loan.returnBook(LOANED_AT.minusDays(1)))
                .isInstanceOf(IllegalArgumentException.class);
    }

    private static Loan loanReturnedOn(LocalDate returnedAt) {
        Loan loan = Loan.reconstitute(UUID.randomUUID(), UUID.randomUUID(), UUID.randomUUID(),
                LOANED_AT, LOANED_AT.plusDays(14), null);
        loan.returnBook(returnedAt);
        return loan;
    }
}
EOF
