package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LoanDateIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void return_on_due_date_has_no_late_fee() throws Exception {
        String loanId = borrowOn("2026-01-01");

        returnOn(loanId, "2026-01-15")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value("2026-01-15"))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void return_one_day_late_charges_100_won() throws Exception {
        String loanId = borrowOn("2026-01-01");

        returnOn(loanId, "2026-01-16")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(1))
                .andExpect(jsonPath("$.lateFee").value(100));
    }

    @Test
    void return_five_days_late_charges_500_won() throws Exception {
        String loanId = borrowOn("2026-01-01");

        returnOn(loanId, "2026-01-20")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(5))
                .andExpect(jsonPath("$.lateFee").value(500));
    }

    @Test
    void return_without_body_uses_today_and_has_no_fee_for_a_fresh_loan() throws Exception {
        String loanId = borrowToday();

        mockMvc.perform(post("/loans/{loanId}/return", loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void return_date_before_loan_date_returns_400() throws Exception {
        String loanId = borrowOn("2026-01-10");

        returnOn(loanId, "2026-01-09").andExpect(status().isBadRequest());
    }

    @Test
    void malformed_date_returns_400() throws Exception {
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(loanBody("2026-13-45")))
                .andExpect(status().isBadRequest());
    }

    private String borrowOn(String loanedAt) throws Exception {
        return borrow(loanBody(loanedAt));
    }

    private String borrowToday() throws Exception {
        String body = objectMapper.writeValueAsString(Map.of("bookId", registerBook(), "memberId", registerMember()));
        return borrow(body);
    }

    private String borrow(String body) throws Exception {
        String response = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("loanId").asText();
    }

    private org.springframework.test.web.servlet.ResultActions returnOn(String loanId, String returnedAt) throws Exception {
        return mockMvc.perform(post("/loans/{loanId}/return", loanId)
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"returnedAt\":\"" + returnedAt + "\"}"));
    }

    private String loanBody(String loanedAt) throws Exception {
        return objectMapper.writeValueAsString(Map.of(
                "bookId", registerBook(),
                "memberId", registerMember(),
                "loanedAt", loanedAt));
    }

    private String registerMember() throws Exception {
        String body = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"최도윤\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("memberId").asText();
    }

    private String registerBook() throws Exception {
        String body = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Working Effectively with Legacy Code\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("id").asText();
    }
}
